fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Vec<Vec<i8>> {
    let r = shape[0] as usize; // Number of rows
    let c = shape[1] as usize; // Number of columns
    let len_a = a.len(); // Length of the input array

    // Initialize the resulting matrix with zeros
    let mut matrix = vec![vec![0; c]; r];

    if len_a == r {
        // Treat `a` as a column vector
        for i in 0..r {
            matrix[i] = vec![a[i]; c]; // Fill each row with the i-th element of `a`
        }
    } else if len_a == c {
        // Treat `a` as a row vector
        for i in 0..r {
            matrix[i].copy_from_slice(&a); // Fill each row with the entire array `a`
        }
    }

    matrix
}